const incidentMonthlyChart=items=>{const w=720,h=300,p={top:24,right:28,bottom:62,left:46},max=Math.max(1,...items.flatMap(item=>[item.planned,item.finished])),plotH=h-p.top-p.bottom,groupW=(w-p.left-p.right)/Math.max(1,items.length),barW=Math.min(52,groupW*.24),y=value=>p.top+plotH-(value/max)*plotH,labels=items.map(item=>item.date?`${DATA_REFRESH_MONTHS[item.date.getMonth()]}/${String(item.date.getFullYear()).slice(-2)}`:'Sem data');return `<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Ações previstas e finalizadas por data de incidente ou acidente">${[0,Math.ceil(max/2),max].map(value=>`<line class="gridline" x1="${p.left}" x2="${w-p.right}" y1="${y(value)}" y2="${y(value)}"/><text class="axis axis-y" x="${p.left-8}" y="${y(value)+4}" text-anchor="end">${value}</text>`).join('')}${items.map((item,index)=>{const center=p.left+groupW*(index+.5),plannedX=center-barW-5,finishedX=center+5;return `<rect x="${plannedX}" y="${y(item.planned)}" width="${barW}" height="${p.top+plotH-y(item.planned)}" rx="5" fill="#e30613"><title>${labels[index]}: ${item.planned} ações previstas</title></rect><text x="${plannedX+barW/2}" y="${y(item.planned)-8}" text-anchor="middle" class="bar-value">${item.planned}</text><rect x="${finishedX}" y="${y(item.finished)}" width="${barW}" height="${p.top+plotH-y(item.finished)}" rx="5" fill="#008f78"><title>${labels[index]}: ${item.finished} ações finalizadas</title></rect><text x="${finishedX+barW/2}" y="${y(item.finished)-8}" text-anchor="middle" class="bar-value">${item.finished}</text><text class="axis" x="${center}" y="${h-22}" text-anchor="middle">${labels[index]}</text>`}).join('')}</svg>`};
const replaceIncidentMonthlyChart=()=>{const panel=[...document.querySelectorAll('[data-safety-control] .panel')].find(item=>/Base operacional · Incidentes e Acidentes/i.test(item.textContent));if(!panel)return;const data=cache[SOURCES.processos.id+'Incidentes e Acidentes'],parsed=accidentRowsFromBase(data||{}),map=new Map();(parsed.rows||[]).forEach(row=>{const d=date(row[parsed.idx.month]),key=d?`${d.getFullYear()}-${d.getMonth()}`:'sem-data',item=map.get(key)||{date:d,planned:0,finished:0};item.planned+=num(row[parsed.idx.registered]);item.finished+=num(row[parsed.idx.resolved]);map.set(key,item)});const chart=panel.querySelector('.chart');if(chart)chart.innerHTML=incidentMonthlyChart([...map.values()].sort((a,b)=>(a.date||0)-(b.date||0)))};
const addRemainingDaysToValidityTables=()=>{const today=new Date();today.setHours(0,0,0,0);document.querySelectorAll('#aso-table,#docs-table,.extra-data-table').forEach(table=>{const headers=[...table.querySelectorAll('thead th')].map(cell=>cell.textContent.toLowerCase());headers.forEach((header,index)=>{if(!/validade|vigência|vigencia|estabilidade/.test(header))return;table.querySelectorAll('tbody tr').forEach(row=>{const cell=row.cells[index];if(!cell||cell.querySelector('.remaining-days'))return;const target=date(cell.textContent.trim());if(!target)return;target.setHours(0,0,0,0);const days=Math.round((target-today)/86400000),note=document.createElement('small');note.className='remaining-days '+(days<0?'remaining-days--expired':'');note.textContent=days>=0?`Faltam ${days} dias`:`Vencido há ${Math.abs(days)} dias`;cell.append(note)})})})};
const renderWithRequestedUpdates=render;
render=async function(){await renderWithRequestedUpdates();addTrainingRatePanel();decorateExtinguisherAlerts();await renderSafetyIncidents();polishSafetyPanels();replaceIncidentMonthlyChart();addRemainingDaysToValidityTables();wireCharts();translateRenderedPage(document.documentElement.lang||'pt-BR')};
